--
-- Table structure for table `pemeriksaan`
--

DROP TABLE IF EXISTS `pemeriksaan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pemeriksaan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pasien_id` bigint unsigned NOT NULL,
  `jadwal_layanan_id` bigint unsigned DEFAULT NULL,
  `tanggal_periksa` date NOT NULL,
  `keluhan` text COLLATE utf8mb4_unicode_ci,
  `kode_icd` text COLLATE utf8mb4_unicode_ci,
  `nama_diagnosa` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `berat_badan` double DEFAULT NULL,
  `tinggi_badan` double DEFAULT NULL,
  `tensi_sistol` int DEFAULT NULL,
  `tensi_diastol` int DEFAULT NULL,
  `respiratory_rate` int DEFAULT NULL,
  `heart_rate` int DEFAULT NULL,
  `temperature` double DEFAULT NULL,
  `nakes_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pemeriksaan_pasien_id_tanggal_periksa_unique` (`pasien_id`,`tanggal_periksa`),
  KEY `pemeriksaan_jadwal_layanan_id_foreign` (`jadwal_layanan_id`),
  KEY `pemeriksaan_nakes_id_foreign` (`nakes_id`),
  CONSTRAINT `pemeriksaan_jadwal_layanan_id_foreign` FOREIGN KEY (`jadwal_layanan_id`) REFERENCES `jadwal_layanan` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pemeriksaan_nakes_id_foreign` FOREIGN KEY (`nakes_id`) REFERENCES `pegawai` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pemeriksaan_pasien_id_foreign` FOREIGN KEY (`pasien_id`) REFERENCES `pasien` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=168 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

