--
-- Table structure for table `persetujuan`
--

DROP TABLE IF EXISTS `persetujuan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `persetujuan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pasien_id` bigint unsigned NOT NULL,
  `template_persetujuan_id` bigint unsigned DEFAULT NULL,
  `petugas_id` bigint unsigned DEFAULT NULL,
  `salinan_judul` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `salinan_teks_pembuka` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `salinan_teks_penutup` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `salinan_poin` json NOT NULL,
  `token_qr` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('menunggu_tanda_tangan','ditandatangani','kedaluwarsa','dibatalkan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'menunggu_tanda_tangan',
  `kedaluwarsa_pada` timestamp NOT NULL,
  `ditandatangani_pada` timestamp NULL DEFAULT NULL,
  `tanda_tangan_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
