INSERT INTO `persetujuan` VALUES (1,152,1,1,'INFORMED CONSENT','Yang bertanda tangan di bawah ini:\r\n\r\nNama: fery yulia rahman\r\nNIK: 3503031106030001\r\nNo. RM: 123719192\r\nTanggal Lahir: 11 Juni 2003\r\nAlamat: menanggal 1 no 8\r\n\r\nDengan ini menyatakan dengan sesungguhnya bahwa saya telah menerima informasi dan memberikan persetujuan terhadap pelayanan kesehatan di Puskesmas Kalijudan, dengan ketentuan sebagai berikut:','Demikian surat persetujuan ini saya buat dengan sadar dan tanpa paksaan dari pihak mana pun.\r\n\r\nSurabaya, 08 Oktober 2026','[\"Saya memahami bahwa data kesehatan saya akan dicatat dan dikelola oleh fasilitas kesehatan.\", \"Saya bersedia mengikuti anjuran medis dan program pemeriksaan rutin yang diberikan.\", \"Saya menyetujui bahwa dokter/petugas berhak mengambil tindakan darurat jika diperlukan demi keselamatan jiwa saya.\"]','2UI0Y3EMo9DWcUtq37RU6nOBEuXImaJzyL00gA03AEy9gm1w332FrxjAYB2O','ditandatangani','2026-10-08 05:05:00','2026-10-08 04:05:41','tanda_tangan/rST0BVfN9b13RusYyraSMeUCH5vqI2fQuh2IYizf.png','127.0.0.1','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/154.0.0.0 Safari/537.36','6b3fc44853e58ae5124c8a27bb3eec33bed9ca7a05d264419a994502084d4cb7','2026-10-08 04:05:00','2026-10-08 04:05:41'),(2,13,1,1,'INFORMED CONSENT','Yang bertanda tangan di bawah ini:\r\n\r\nNama: HANDAYANI\r\nNIK: 3578267006690014\r\nNo. RM: 01.1358/01/KJ/ILP24/PROLANIS DM/CKG26\r\nTanggal Lahir: 30 Juni 1969\r\nAlamat: KALIJUDAN 12/41, KALIJUDAN, MULYOREJO, SURABAYA\r\n\r\nDengan ini menyatakan dengan sesungguhnya bahwa saya telah menerima informasi dan memberikan persetujuan terhadap pelayanan kesehatan di Puskesmas Kalijudan, dengan ketentuan sebagai berikut:','Demikian surat persetujuan ini saya buat dengan sadar dan tanpa paksaan dari pihak mana pun.\r\n\r\nSurabaya, 10 Oktober 2026','[\"Saya memahami bahwa data kesehatan saya akan dicatat dan dikelola oleh fasilitas kesehatan.\", \"Saya bersedia mengikuti a