INSERT INTO `template_persetujuan` VALUES (1,'INFORMED CONSENT','Yang bertanda tangan di bawah ini:\r\n\r\nNama: {nama_pasien}\r\nNIK: {nik}\r\nNo. RM: {no_rm}\r\nTanggal Lahir: {tanggal_lahir}\r\nAlamat: {alamat}\r\n\r\nDengan ini menyatakan dengan sesungguhnya bahwa saya telah menerima informasi dan memberikan persetujuan terhadap pelayanan kesehatan di Puskesmas Kalijudan, dengan ketentuan sebagai berikut:','Demikian surat persetujuan ini saya buat dengan sadar dan tanpa paksaan dari pihak mana pun.\r\n\r\nSurabaya, {tanggal}',1,'2026-10-08 04:04:30','2026-10-08 04:04:30');
